ee:message.ee:set-payload:
%dw 2.0
output application/json skipNullOn="everywhere"
import substring from dw::core::Strings
var responseDate = payload.feasibilityResponse.outputMessage."M6ConsultarBloquearRecursos-RS".DetalleRespuesta.FechaRespuesta
var statusResp = payload.feasibilityResponse.outputMessage."M6ConsultarBloquearRecursos-RS".DetalleRespuesta.Resultado
---
{
    "GetFeasibilityFTTHOutput":{
        "WSResponseHeader2": {
            "System":{
                "name": "" ,
                "correlationID": vars.correlationId,
                "source": "portal-xapi-services"
            },
            "Service":{
                "status": payload.feasibilityResponse.outputMessage."M6ConsultarBloquearRecursos-RS".DetalleRespuesta.Resultado,
                "responseDate": substring (responseDate, 0, 4) ++ '/' ++ substring (responseDate, 4, 6) ++ '/' ++ substring (responseDate, 6, 8) ++ ' ' ++ substring (responseDate, 8, 10) ++ ':' ++ substring (responseDate, 10, 12) ++ ':' ++ substring (responseDate, 12, 14),
                "statusDetail":{
                    "errorCode": payload.feasibilityResponse.outputMessage."M6ConsultarBloquearRecursos-RS".DetalleRespuesta.CodigoErrorResultado,
                    "errorDetailCode": "",
                    "errorMessagge": payload.feasibilityResponse.outputMessage."M6ConsultarBloquearRecursos-RS".DetalleRespuesta.DescripcionErrorResultado
                }
            }, 
            "GetFeasibilityFTTHResponse": if(statusResp == "OK"){
    			"Feasibility": payload.feasibilityResponse.outputMessage."M6ConsultarBloquearRecursos-RS".RespuestaFactibilidad
    		} else null
        }
    }
}
